-- Giaodoan Merchant CRM - initial schema.
-- Derived from the 14 Stitch screens in design/. See docs/DATA_MODEL.md for the column -> screen map.
-- Conventions:
--   * uuid primary keys (gen_random_uuid), created_at default now()
--   * enums are text + check constraints (labels live in src/lib/constants.ts)
--   * every child table has an FK to merchants (on delete cascade)
--   * human-readable codes (MC-3926, TK-8841, ...) are generated by sequences so inserts can omit them
--   * RLS is ON everywhere with PUBLIC anon policies (the user asked for a public database)

-- ---------------------------------------------------------------------------
-- Sequences for human-readable codes (seed.sql restarts them above the seeded codes)
-- ---------------------------------------------------------------------------
create sequence if not exists merchant_code_seq start 3927;
create sequence if not exists ticket_code_seq start 8842;
create sequence if not exists ticket_message_seq start 4;
create sequence if not exists contact_code_seq start 6843;
create sequence if not exists faq_code_seq start 111;
create sequence if not exists subscription_code_seq start 3;
create sequence if not exists invoice_no_seq start 88393;

-- ---------------------------------------------------------------------------
-- staff: internal Giaodoan employees (account managers, onboarding / CSKH specialists, FAQ editors)
-- ---------------------------------------------------------------------------
create table if not exists staff (
  id          uuid primary key default gen_random_uuid(),
  code        text unique,                 -- GD-NV082
  full_name   text not null,               -- Nguyen Van A
  title       text,                        -- Senior Partner Specialist
  role_label  text,                        -- short role shown in call logs: Onboarding Lead
  team        text,                        -- Doi F&B Hub DN
  email       text,
  phone       text,
  ext         text,                        -- internal extension (May le)
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- merchants: F&B partners. Hub table, everything else points here.
-- ---------------------------------------------------------------------------
create table if not exists merchants (
  id                    uuid primary key default gen_random_uuid(),
  code                  text not null unique default ('MC-' || nextval('merchant_code_seq')),  -- MC-3926 (UI shows "#MC-3926")
  name                  text not null,
  category              text,              -- tagline: "Ca phe & Do uong chill ban dem"
  status                text not null default 'new'
                        check (status in ('onboarding','active','new','consulted','stopped')),
  phone                 text not null,
  email                 text,              -- invoice / reconciliation email
  personal_email        text,              -- manager personal email
  address               text not null,     -- short address used in tables
  address_full          text,              -- official business address
  region                text,              -- province / city: Da Nang, Ha Noi, TP. Ho Chi Minh ...
  district              text,              -- Hai Chau, Quan 1 ...
  area_label            text,              -- "Trung tam Hai Chau"
  lat                   numeric(9,5),
  lng                   numeric(9,5),
  delivery_radius_km    numeric(4,1),
  pickup_time_label     text,              -- "5 - 8 phut"
  is_open               boolean not null default true,   -- store currently accepting orders
  contact_name          text,              -- primary legal representative
  contact_title         text,
  contact_verified      boolean not null default false,  -- "Da xac minh CCCD"
  call_hours            text,              -- "08:00 - 22:30 hang ngay"
  zalo_group            text,
  zalo_group_note       text,
  business_license      text,              -- GPKD-2024/DN-771
  tax_code              text,              -- MST (invoice)
  branch_type           text,              -- "Chi nhanh Doc lap"
  partner_tier          text,              -- "Platinum Partner" (hero badge on detail page)
  icon                  text,              -- material symbol used as avatar fallback (churn list)
  emoji                 text,              -- emoji avatar used in the contact-log list
  image_url             text,              -- list thumbnail
  cover_url             text,              -- detail hero image
  map_url               text,              -- detail map backdrop
  account_manager_id    uuid references staff(id) on delete set null,
  created_by_id         uuid references staff(id) on delete set null,
  take_rate_pct         numeric(4,1),      -- commission (18.5)
  payout_schedule       text,              -- "Thu 3 & Thu 6 hang tuan"
  bank_account          text,              -- "MB Bank - 8839268888"
  contract_end          date,              -- current contract expiry (drives "Sap het han HD")
  gmv_month_vnd         bigint,
  gmv_growth_pct        numeric(5,1),
  orders_month          integer,
  completion_rate_pct   numeric(4,1),
  aov_vnd               integer,
  best_seller           text,
  prep_time_min         numeric(3,1),
  stats_updated_at      timestamptz,
  created_at            timestamptz not null default now()
);
create index if not exists merchants_status_idx on merchants(status);
create index if not exists merchants_region_idx on merchants(region);

-- Extra people at a merchant (onboarding detail "Dau moi lien he"). Primary rep lives on merchants.contact_*.
create table if not exists merchant_contacts (
  id           uuid primary key default gen_random_uuid(),
  merchant_id  uuid not null references merchants(id) on delete cascade,
  full_name    text not null,
  title        text,                       -- "Chu co so (Quan ly chung)"
  phone        text,
  sort_order   integer not null default 0,
  created_at   timestamptz not null default now()
);
create index if not exists merchant_contacts_merchant_idx on merchant_contacts(merchant_id);

-- ---------------------------------------------------------------------------
-- Subscriptions: plans catalogue, merchant contracts, invoices
-- ---------------------------------------------------------------------------
create table if not exists service_plans (
  id               uuid primary key default gen_random_uuid(),
  code             text not null unique check (code in ('silver','gold','diamond')),
  name             text not null,          -- Goi Bac (Silver)
  tier_label       text,                   -- Goi Khoi Diem
  badge            text,                   -- "Pho bien nhat - Best Value"
  icon             text,                   -- material symbol
  price_month_vnd  bigint not null,
  price_year_vnd   bigint not null,
  year_note        text,                   -- "Hoac 12.000.000 d / nam (Tiet kiem 2 thang)"
  commission_pct   numeric(4,1),           -- platform fee shown on the card
  features         text[] not null default '{}',
  sort_order       integer not null default 0,
  created_at       timestamptz not null default now()
);

-- One row per contract. A merchant has many (history); exactly one should have is_current = true.
create table if not exists subscriptions (
  id                  uuid primary key default gen_random_uuid(),
  code                text not null unique default ('GDV-' || nextval('subscription_code_seq')),  -- GDV-GLD-02
  merchant_id         uuid not null references merchants(id) on delete cascade,
  plan_id             uuid references service_plans(id) on delete set null,
  plan_name           text not null,       -- snapshot, e.g. "Goi Vang (Gold)" / "Dung Thu Khai Truong"
  plan_tier           text not null check (plan_tier in ('silver','gold','diamond','trial')),
  cycle_months        integer,             -- 12, 6, 1 (null for trial)
  cycle_label         text,                -- "12 Thang", "15 Ngay"
  contract_note       text,                -- "Hop dong 1 nam (Sunmi POS)"
  list_price_vnd      bigint,              -- undiscounted price (11.988.000)
  discount_pct        numeric(4,1) not null default 0,
  amount_vnd          bigint not null,     -- amount actually paid / billed (10.800.000)
  signed_at           date,
  start_date          date not null,
  end_date            date not null,
  status              text not null default 'active' check (status in ('active','completed','cancelled')),
  is_current          boolean not null default false,
  auto_renew          boolean not null default false,
  payment_method      text,                -- "Chuyen khoan VCB"
  payment_ref         text,                -- "#VCB-8839210"
  benefits            jsonb not null default '[]'::jsonb,   -- [{icon,title,description}]
  account_manager_id  uuid references staff(id) on delete set null,
  created_at          timestamptz not null default now()
);
create index if not exists subscriptions_merchant_idx on subscriptions(merchant_id);
create index if not exists subscriptions_end_idx on subscriptions(end_date);

create table if not exists invoices (
  id                    uuid primary key default gen_random_uuid(),
  number                text not null unique default ('HD-' || to_char(now(), 'YYYY') || '-' || nextval('invoice_no_seq')),  -- HD-2025-88392
  merchant_id           uuid not null references merchants(id) on delete cascade,
  subscription_id       uuid references subscriptions(id) on delete set null,
  issued_at             timestamptz not null default now(),
  einvoice_series       text,              -- 1C24TGD
  einvoice_no           text,              -- 0029841
  status                text not null default 'paid' check (status in ('paid','pending','void')),
  line_title            text,              -- "Goi Dich Vu Vang (Gold Plan F&B) - ..."
  term_months           integer,
  list_price_vnd        bigint,
  discount_vnd          bigint not null default 0,
  discount_pct          numeric(4,1) not null default 0,
  total_vnd             bigint not null,
  amount_in_words       text,
  vat_note              text default '(VAT 0% phan mem)',
  previous_contract_code text,             -- GDV-SLV-01
  previous_end_date     date,
  new_start_date        date,
  new_end_date          date,
  payment_method        text,
  payment_ref           text,              -- VCB-8839210
  payment_note          text,              -- "Khop lenh tu dong qua OpenBanking"
  merchant_rep_name     text,              -- signer on merchant side
  merchant_rep_phone    text,
  merchant_signed_at    timestamptz,
  merchant_sign_provider text,             -- VNPT-CA
  issuer_unit           text,              -- "Phong Quan ly & Phat trien Doi tac Giaodoan - Mien Trung"
  issuer_staff_id       uuid references staff(id) on delete set null,
  issuer_sign_note      text,              -- "Ky so Viettel-CA - GD-AUTH-8839"
  created_at            timestamptz not null default now()
);
create index if not exists invoices_merchant_idx on invoices(merchant_id);
create index if not exists invoices_subscription_idx on invoices(subscription_id);

-- ---------------------------------------------------------------------------
-- Onboarding: one onboarding per merchant, 5 steps, sub-tasks on a step
-- ---------------------------------------------------------------------------
create table if not exists onboardings (
  id            uuid primary key default gen_random_uuid(),
  merchant_id   uuid not null unique references merchants(id) on delete cascade,
  assignee_id   uuid references staff(id) on delete set null,
  steps_done    integer not null default 0 check (steps_done between 0 and 5),
  owner_label   text,                      -- "Chu so huu: Le Van Nam" (list sub-line)
  started_at    timestamptz,
  go_live_date  date,                      -- target / actual go-live
  sla_note      text,                      -- "Nhanh hon 1.5 ngay so voi SLA chuan"
  sla_detail    text,
  created_at    timestamptz not null default now()
);

create table if not exists onboarding_steps (
  id              uuid primary key default gen_random_uuid(),
  onboarding_id   uuid not null references onboardings(id) on delete cascade,
  step_no         integer not null check (step_no between 1 and 5),
  title           text not null,
  description     text,
  status          text not null default 'pending' check (status in ('done','in_progress','pending')),
  completed_at    timestamptz,
  completed_by    text,                    -- "Admin CSKH (Le Thanh)"
  planned_label   text,                    -- "23/10 - 25/10/2024"
  meta            jsonb not null default '{}'::jsonb,   -- per-step facts: bank, menu_count, target status ...
  guide_goal      text,                    -- right panel "Muc tieu can dat"
  guide_checklist text[] not null default '{}',
  created_at      timestamptz not null default now(),
  unique (onboarding_id, step_no)
);

create table if not exists onboarding_tasks (
  id          uuid primary key default gen_random_uuid(),
  step_id     uuid not null references onboarding_steps(id) on delete cascade,
  title       text not null,
  done        boolean not null default false,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now()
);
create index if not exists onboarding_tasks_step_idx on onboarding_tasks(step_id);

-- ---------------------------------------------------------------------------
-- Support tickets
-- ---------------------------------------------------------------------------
create table if not exists support_tickets (
  id            uuid primary key default gen_random_uuid(),
  code          text not null unique default ('TK-' || nextval('ticket_code_seq')),   -- TK-8841
  merchant_id   uuid not null references merchants(id) on delete cascade,
  branch_label  text,                      -- "Chi nhanh 1 - Q.1, TP. Ho Chi Minh"
  category      text not null check (category in ('payment','store','login','onboarding','feedback','other')),
  subject       text,
  body          text,
  priority      text not null default 'normal' check (priority in ('low','normal','high')),   -- high = "Cao (Gap)"
  status        text not null default 'new'
                check (status in ('new','processing','waiting_merchant','resolved','closed')),
  assignee_id   uuid references staff(id) on delete set null,
  sla_due_at    timestamptz,
  responded_at  timestamptz,
  status_note   text,                      -- "Doi bo sung giay phep KD" / "Da ghi nhan & phan hoi"
  updated_at    timestamptz not null default now(),
  updated_by    text,
  created_at    timestamptz not null default now()
);
create index if not exists support_tickets_merchant_idx on support_tickets(merchant_id);
create index if not exists support_tickets_status_idx on support_tickets(status);

create table if not exists ticket_attachments (
  id           uuid primary key default gen_random_uuid(),
  ticket_id    uuid not null references support_tickets(id) on delete cascade,
  file_name    text not null,
  size_label   text,                       -- "240 KB"
  kind_label   text,                       -- "Bang ke Excel"
  kind         text not null default 'other' check (kind in ('xlsx','pdf','image','other')),
  url          text,
  uploaded_by  text not null default 'merchant' check (uploaded_by in ('merchant','staff')),
  created_at   timestamptz not null default now()
);
create index if not exists ticket_attachments_ticket_idx on ticket_attachments(ticket_id);

create table if not exists ticket_messages (
  id              uuid primary key default gen_random_uuid(),
  code            text not null unique default ('PH-' || lpad(nextval('ticket_message_seq')::text, 2, '0')),  -- PH-01
  ticket_id       uuid not null references support_tickets(id) on delete cascade,
  handler_id      uuid references staff(id) on delete set null,
  handler_name    text,                    -- snapshot "Nguyen Van A"
  handler_role    text,                    -- "Tai chinh & Doi soat"
  responder_name  text,                    -- "Nguoi phan hoi" column
  content         text not null,
  channel         text not null default 'app' check (channel in ('app','zalo_sms','email','internal')),
  created_at      timestamptz not null default now()
);
create index if not exists ticket_messages_ticket_idx on ticket_messages(ticket_id);

create table if not exists reply_templates (
  id          uuid primary key default gen_random_uuid(),
  title       text not null,
  body        text not null,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Contact history (calls, Zalo, visits, meetings, notes)
-- ---------------------------------------------------------------------------
create table if not exists contact_logs (
  id               uuid primary key default gen_random_uuid(),
  code             text not null unique default ('LH-' || nextval('contact_code_seq')),   -- LH-6842
  merchant_id      uuid not null references merchants(id) on delete cascade,
  staff_id         uuid references staff(id) on delete set null,
  actor_name       text,                   -- fallback when staff_id is null ("He thong tu dong")
  channel          text not null check (channel in ('voip','zalo','visit','meet','note')),
  channel_label    text,                   -- "VoIP In-app", "Zalo OA + Call", "Google Meet"
  contact_person   text,                   -- "Anh Long (Chu quan)"
  purpose          text,                   -- "Tu van gia han goi"
  content          text not null,
  tags             text[] not null default '{}',
  status           text not null default 'success' check (status in ('success','no_answer','hung_up')),
  duration_seconds integer not null default 0,
  has_recording    boolean not null default false,
  needs_callback   boolean not null default false,
  callback_at      timestamptz,
  occurred_at      timestamptz not null default now(),
  created_at       timestamptz not null default now()
);
create index if not exists contact_logs_merchant_idx on contact_logs(merchant_id);
create index if not exists contact_logs_occurred_idx on contact_logs(occurred_at desc);

-- ---------------------------------------------------------------------------
-- Churn risk signals (one row per merchant x signal)
-- ---------------------------------------------------------------------------
create table if not exists churn_risks (
  id            uuid primary key default gen_random_uuid(),
  merchant_id   uuid not null references merchants(id) on delete cascade,
  risk_type     text not null check (risk_type in ('expiring','order_gap','app_inactive')),
  risk_level    text not null default 'medium' check (risk_level in ('critical','high','medium')),
  expires_on    date,                      -- service expiry; UI shows "Con N ngay / thang"
  inactive_days integer,
  alert_text    text,                      -- "10 ngay khong phat sinh don" ; null for expiring rows
  handled       boolean not null default false,   -- "Da lien he xu ly"
  handled_at    timestamptz,
  assignee_id   uuid references staff(id) on delete set null,
  note          text,
  detected_at   timestamptz not null default now(),
  created_at    timestamptz not null default now(),
  unique (merchant_id, risk_type)
);
create index if not exists churn_risks_merchant_idx on churn_risks(merchant_id);

-- ---------------------------------------------------------------------------
-- Merchant activity log
-- ---------------------------------------------------------------------------
create table if not exists activity_logs (
  id            uuid primary key default gen_random_uuid(),
  merchant_id   uuid not null references merchants(id) on delete cascade,
  occurred_at   timestamptz not null default now(),
  action_type   text not null check (action_type in (
                  'pause_orders','resume_orders','update_store','update_menu','confirm_order',
                  'cancel_order','create_promo','login_failed','pos_sync','update_document')),
  action_label  text not null,             -- "Ngung nhan don hom nay"
  subtitle      text,                      -- "Van hanh quan"
  icon          text,                      -- material symbol
  category      text not null check (category in ('orders','config','security')),  -- filter tabs
  details       text,
  old_value     text,
  new_value     text,
  extra         jsonb not null default '{}'::jsonb,   -- order_code, amount_vnd, voucher_code, error_code, reason ...
  actor_type    text not null default 'owner' check (actor_type in ('owner','cashier','system','support','guest')),
  actor_name    text,
  actor_role    text,
  device        text,
  ip            text,
  status        text not null default 'success' check (status in ('success','failed','warning','cancelled')),
  created_at    timestamptz not null default now()
);
create index if not exists activity_logs_merchant_idx on activity_logs(merchant_id, occurred_at desc);

-- ---------------------------------------------------------------------------
-- FAQ
-- ---------------------------------------------------------------------------
create table if not exists faqs (
  id             uuid primary key default gen_random_uuid(),
  code           text not null unique default ('FAQ-' || nextval('faq_code_seq')),   -- FAQ-101
  category       text not null check (category in ('payout','operations','account','policy','promotion')),
  question       text not null,
  answer         text not null,
  icon           text,
  view_count     integer not null default 0,
  is_visible     boolean not null default true,
  audience       text not null default 'all' check (audience in ('all','new','chain')),
  updated_by_id  uuid references staff(id) on delete set null,
  updated_at     timestamptz not null default now(),
  created_at     timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Promotions (CTKM)
-- ---------------------------------------------------------------------------
create table if not exists promotions (
  id            uuid primary key default gen_random_uuid(),
  code          text not null unique,      -- KM-FNB-2025 (typed by the user, drawer prefills "#KM-XMAS-2025")
  name          text not null,
  description   text,
  promo_type    text not null check (promo_type in ('percent','freeship','combo','voucher','bogo','flash_sale')),
  discount_label text,                     -- "Giam 30% (Max 50K)"
  icon          text,
  sponsor       text not null default 'giaodoan_100'
                check (sponsor in ('giaodoan_100','split_50_50','giaodoan_70_mc_30','merchant_100')),
  participants  integer not null default 0,       -- platform-wide merchant count shown in the table
  start_date    date not null,
  end_date      date not null,
  status        text not null default 'upcoming' check (status in ('running','upcoming','ended')),
  is_active     boolean not null default true,    -- on/off toggle in the table
  budget_vnd    bigint not null default 0,
  spent_vnd     bigint not null default 0,
  revenue_vnd   bigint not null default 0,        -- revenue of orders using the promo
  region        text not null default 'Toàn quốc',
  audience      text not null default 'all' check (audience in ('all','top_tier','list')),
  terms         text,
  created_at    timestamptz not null default now()
);

create table if not exists promotion_merchants (
  id               uuid primary key default gen_random_uuid(),
  promotion_id     uuid not null references promotions(id) on delete cascade,
  merchant_id      uuid not null references merchants(id) on delete cascade,
  orders_count     integer not null default 0,
  uplift_pct       numeric(5,1),
  revenue_gain_vnd bigint not null default 0,
  created_at       timestamptz not null default now(),
  unique (promotion_id, merchant_id)
);

create table if not exists promotion_budgets (
  id         uuid primary key default gen_random_uuid(),
  region     text not null,
  quarter    text not null,                -- Q4/2025
  limit_vnd  bigint not null,
  spent_vnd  bigint not null default 0,
  created_at timestamptz not null default now(),
  unique (region, quarter)
);

-- ---------------------------------------------------------------------------
-- RLS: public anon select / insert / update / delete on every table + grants
-- ---------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array[
    'staff','merchants','merchant_contacts','service_plans','subscriptions','invoices',
    'onboardings','onboarding_steps','onboarding_tasks',
    'support_tickets','ticket_attachments','ticket_messages','reply_templates',
    'contact_logs','churn_risks','activity_logs','faqs',
    'promotions','promotion_merchants','promotion_budgets'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_public_select', t);
    execute format('drop policy if exists %I on public.%I', t || '_public_insert', t);
    execute format('drop policy if exists %I on public.%I', t || '_public_update', t);
    execute format('drop policy if exists %I on public.%I', t || '_public_delete', t);
    execute format('create policy %I on public.%I for select to anon, authenticated using (true)', t || '_public_select', t);
    execute format('create policy %I on public.%I for insert to anon, authenticated with check (true)', t || '_public_insert', t);
    execute format('create policy %I on public.%I for update to anon, authenticated using (true) with check (true)', t || '_public_update', t);
    execute format('create policy %I on public.%I for delete to anon, authenticated using (true)', t || '_public_delete', t);
    execute format('grant select, insert, update, delete on public.%I to anon, authenticated', t);
  end loop;
end
$$;

grant usage on schema public to anon, authenticated;
-- inserts that rely on code defaults call nextval(); the roles need sequence privileges
grant usage, select on all sequences in schema public to anon, authenticated;

notify pgrst, 'reload schema';
